"""O09 independent qualification specification; no planner imports or I/O.
The caller/harness pins the contract profile independently of supplied proof.
Currentness is an independently admitted persisted invalidation view.
"""
import hashlib, json, re

def canonical(v):
    def check(x):
        if type(x) not in (dict,list,str,int,bool,type(None)): raise ValueError('JSON type')
        if type(x) is dict:
            if any(type(k) is not str for k in x): raise ValueError('key')
            for y in x.values(): check(y)
        if type(x) is list:
            for y in x: check(y)
    check(v)
    return json.dumps(v,sort_keys=True,separators=(',',':'),ensure_ascii=False,allow_nan=False).encode('utf-8')
def digest(v): return hashlib.sha256(canonical(v)).hexdigest()
def raw(v): return hashlib.sha256(v.encode('utf-8')).hexdigest()
def fields(v,names): return type(v) is dict and set(v)==set(names.split())
def parse(text):
    def pairs(items):
        d={}
        for k,v in items:
            if k in d: raise ValueError('duplicate key')
            d[k]=v
        return d
    return json.loads(text,object_pairs_hook=pairs,parse_constant=lambda _: (_ for _ in ()).throw(ValueError('constant')))
def reject(clause): return {'accepted':False,'failed_clause':clause,'slot_resolved_supported':False}
def admit(profile,state,currentness):
    try: return _admit(profile,state,currentness)
    except (KeyError,TypeError,ValueError,UnicodeError): return reject('C00_SCHEMA')
def _admit(p,s,c):
    if not fields(s,'schema mode profile_pin proof documents') or s['schema']!='O09-SLOT-PROOF-INPUT-1' or s['mode']!='SYNTHETIC_QUALIFICATION_ONLY' or s['profile_pin']!=digest(p): return reject('C00_SCHEMA')
    q=s['proof']
    if q is None:return reject('C01_PROOF_REQUIRED')
    if not fields(q,'identity schema predicate slot value value_domain proof_type scope lineage envelope provenance prerequisites mapping supports') or q['schema']!='O09-SLOT-PROOF-1':return reject('C00_SCHEMA')
    if q['slot']!=p['slot'] or q['predicate']!=p['predicate']:return reject('C02_TARGET')
    if q['proof_type']!=p['proof_type']:return reject('C03_COMPLETION_PROOF_TYPE')
    if type(q['value']) is not str or q['value']!=p['value'] or q['value_domain']!=p['value_domain']:return reject('C04_VALUE_DOMAIN')
    if q['scope']!=p['resolution_scope']:return reject('C05_SCOPE')
    if q['lineage']!=p['lineage']:return reject('C06_LINEAGE')
    if q['envelope']!=p['envelope']:return reject('C07_ENVELOPE')
    if q['prerequisites']!=p['prerequisites']:return reject('C08_PREREQUISITES')
    if q['provenance']!=p['provenance']:return reject('C09_PROVENANCE')
    if q['mapping']!=p['mapping']:return reject('C10_MAPPING')
    if q['supports']!=p['supports']:return reject('C11_SUPPORT_BINDINGS')
    if not fields(c,'snapshot evaluation sources') or c['snapshot']!=p['snapshot'] or c['evaluation']!='PINNED_SNAPSHOT_ONLY' or set(c['sources'])!=set(p['supports']):return reject('C12_CURRENTNESS')
    for role,pin in p['supports'].items():
        if c['sources'][role]!={'identity':pin['identity'],'state':'CURRENT_AT_PINNED_SNAPSHOT'}:return reject('C12_CURRENTNESS')
    if type(s['documents']) is not dict or set(s['documents'])!=set(p['supports']):return reject('C13_SOURCE_BYTES')
    for role,pin in p['supports'].items():
        if type(s['documents'][role]) is not str or raw(s['documents'][role])!=pin['identity']['sha256']:return reject('C13_SOURCE_BYTES')
    obj=parse(s['documents']['candidate']);body={k:v for k,v in obj.items() if k not in ['identity','canonical_byte_length']}
    if type(obj['canonical_byte_length']) is not int or obj['canonical_byte_length']!=len(canonical(body)) or obj['identity']!=p['candidate_prefix']+digest(body):return reject('C14_SOURCE_IDENTITY')
    if p['slot']=='slot:authenticated_inputs.InvocationAttemptId':
        if obj['record_type']!='INVOCATION-CANDIDATE-1' or obj['identity']!=q['value']:return reject('C14_SOURCE_IDENTITY')
        if {k:obj[k] for k in p['envelope']}!=p['envelope'] or {k:obj[k] for k in p['lineage']}!=p['lineage']:return reject('C15_SOURCE_CORRESPONDENCE')
    elif p['slot']=='slot:authenticated_inputs.profile_sha256':
        if obj['schema']!='CURRENT-R4-PROFILE-ROOT-CANDIDATE-1' or digest(body)!=q['value']:return reject('C14_SOURCE_IDENTITY')
        blocks=re.findall(r'```json\s*\n(.*?)\n```',s['documents']['release'],re.S)
        if len(blocks)!=1:return reject('C15_SOURCE_CORRESPONDENCE')
        rel=parse(blocks[0]);rb={k:v for k,v in rel.items() if k!='authority_id'}
        if rel['authority_id']!='ReleasedProfileAuthority-sha256:'+digest(rb) or rel['authority_id']!=p['release_authority'] or rel['record_type']!='RELEASED-PROFILE-AUTHORITY-1' or rel['status']!='ISSUED' or rel['candidate_profile_identity']!=obj['identity']:return reject('C15_SOURCE_CORRESPONDENCE')
        if {k:rel[k] for k in p['envelope']}!=p['envelope'] or obj['scope']['lineage']!=p['lineage']['lineage'] or rel['lineage']!=p['lineage']['lineage']:return reject('C15_SOURCE_CORRESPONDENCE')
        if any(obj['scope'][k]!=p['envelope'][k] for k in ['runtime','controller_store']):return reject('C15_SOURCE_CORRESPONDENCE')
    else:return reject('C02_TARGET')
    # Source-pinned result text is the historical acceptance, not an input PASS flag.
    for text in p['required_result_excerpts']:
        if text not in s['documents']['acceptance']:return reject('C16_ACCEPTANCE_RECORD')
    if q['identity']!={'domain':'CONTENT_IDENTITY','namespace':'O09SlotProof-sha256','sha256':digest({k:v for k,v in q.items() if k!='identity'})}:return reject('C17_PROOF_IDENTITY')
    return {'accepted':True,'failed_clause':None,'slot_resolved_supported':True,'slot':q['slot'],'value':q['value'],'resolution_scope':q['scope'],'evaluation':'PINNED_SNAPSHOT_ONLY','authority_granted':False,'root_transition':'UNCHANGED'}
